INSERT INTO `crwl_reviews` VALUES (10611,'ChIJQzc6B11MZTURARoIn4nc6YY',NULL,'수목토김밥','google','ChdDSUhNMG9nS0VJQ0FnTURvbzlXazdnRRAB',5,'어렸을때 부터 지금까지 단골인데(오늘도 먹음)\n진짜 너무....하...너무 맛있어요\n13년인생중 여기보다 맛있는곳못가봄...♡',36.324126799999995,127.3481023,'2025-04-28 00:33:37','2026-03-11 01:15:17'),(10612,'ChIJQzc6B11MZTURl4W-eEkd8ws',NULL,'병규돈까스','google','ChdDSUhNMG9nS0VJQ0FnSUQ2c1BmZThRRRAB',5,'',36.324126799999995,127.3481023,'2021-09-18 09:36:49','2026-03-11 01:15:19'),(10613,'ChIJQzc6B11MZTURapVJKZotME8',4043,'봉구스밥버거목원대점','google','ChZDSUhNMG9nS0VJQ0FnSUR5aXJMNGJnEAE',5,'아... 중1~고2학년의\n충주의중학교 갈때...\n여기의서❗ 시켜 먹었\n언는데... 아... 이사...\n가고... 다쳐서... 못 먹\n었언는데... 아... 그립\n다... 그리웡... 치킨 마\n요... ',36.324126799999995,127.3481023,'2021-03-02 12:06:18','2026-03-11 01:15:19'),(10614,'ChIJ9YQJCz1MZTUR0gVL8_YCQFs',NULL,'은혜식당','google','Ci9DQUlRQUNvZENodHljRjlvT25RNE1FNVlaVmhVY0dwV2JYWmZWWFpPVTFORGVVRRAB',1,'저녁에 제육백반과 소주 2병 식사를 했습니다. 사장님은 친절하셨으나, 소개해준 자리는 너무 더러웠고 심지어 물티슈로 닦았더니 5번 닦아도 지워지지 않는 꾸정물이 나왔습니다. 후에 콩나물국을 받았지만 국그릇은 너무 더러워 교체했고 다 먹고 결제할 때도 16000원이 아닌 18000원으로 결제하여 이를 따지니 2000원 현금으로 환불해주네요... 여러모로 찜찜한 경험이였습니다',36.3169908,127.36959540000001,'2025-09-04 00:11:25','2026-03-11 01:15:21'),(10615,'ChIJ9YQJCz1MZTUR0gVL8_YCQFs',NULL,'은혜식당','google','ChdDSUhNMG9nS0VJQ0FnSUNDcXBqTXZBRRAB',5,'아주 맛있는 식당~\n순두부 찌개(6.) 먹었는데 반찬으로 김치전도 주시고 옆에 손님으로 오신 단골 선생님은 맥주도 한잔 주시고 정감 있는 식당입니다ㅎ',36.3169908,127.36959540000001,'2020-08-19 06:49:05','2026-03-11 01:15:21'),(10616,'ChIJ9YQJCz1MZTUR0gVL8_YCQFs',NULL,'은혜식당','google','ChdDSUhNMG9nS0VMV3lnN3JuLVlDaTJnRRAB',5,'매일 먹을수 있는 동네 사랑방식당.',36.3169908,127.36959540000001,'2025-06-01 14:19:50','2026-03-11 01:15:21'),(10617,'ChIJ9YQJCz1MZTUR0gVL8_YCQFs',NULL,'은혜식당','google','ChdDSUhNMG9nS0VJQ0FnSUNPMHUybGhnRRAB',5,'진짜 최고최고 너무너무 맜있어요!\n서비스가최고 복많이 받으세요',36.3169908,127.36959540000001,'2022-06-05 20:43:10','2026-03-11 01:15:21'),(10618,'ChIJ9YQJCz1MZTUR0gVL8_YCQFs',NULL,'은혜식당','google','ChdDSUhNMG9nS0VJQ0FnSUNxb3U2anZnRRAB',5,'맛있어요\n올래용ㅇㅇㅇㅇㅇㅇ',36.3169908,127.36959540000001,